        <div class="header">
            <el-button text circle icon="ArrowLeft" size="large" style="font-size: 1.25em;" @click="router.back()"></el-button>

            <img class="avatar" :src="post.avatarUrl">
            <div class="name">{{ post.nickName }}</div>

            <el-button v-if="!authorFollowed" round @click="Follow.follow(post.userId)">
                <span style="color: #855D12; font-size: 1.7em; margin-right: 4px;">+</span>关注
            </el-button>
            <el-button v-else round>已关注</el-button>

            <el-button round icon="mdiShareOutline" style="font-size: 1.5em; color: #A0814D;"></el-button>
        </div>

        <el-carousel v-if="post.urls" trigger="click" height="40vh">
            <el-carousel-item v-for="item in post.urls">
                <img v-if="item.type == 0" :src="item.url">
                <video v-if="item.type == 1" :src="item.url"></video>
            </el-carousel-item>
        </el-carousel>

        <h3 class="title">{{ post.title }}</h3>
        <div class="body" v-html="post.content"></div>

        <div v-if="typeof post.tag == 'string'" class="tags">
            <span v-for="item in post.tag.split(' ')">{{ item }}</span>
        </div>

